#include <iostream>
using namespace std;

// Recursive function to calculate nth Fibonacci number
int fibonacci(int n) {
    // Base case: n = 0 or 1 returns the respective Fibonacci number
    if (n <= 1)
        return n;

    // Recursive call to compute previous two Fibonacci numbers
    int fib_n1 = fibonacci(n - 1); // n-1th Fibonacci
    int fib_n2 = fibonacci(n - 2); // n-2th Fibonacci

    // Add them to obtain nth Fibonacci number
    return fib_n1 + fib_n2;
}

int main() {
    int n; // input nth position

    cout << "Enter the position of the Fibonacci number: ";
    cin >> n;

    // Call the recursive function to find nth Fibonacci
    int fib_n = fibonacci(n);

    cout << "The " << n << "th Fibonacci number is: " << fib_n << endl;

    return 0;
}
```

To compile and run the program, save it to a file named `fibonacci.cpp` and then use the following commands:

```sh
